// dice.js — Dice So Nice dice sets for Legend in the Mist.
//
// Two d6 sets are registered:
//  • Acorns  — a custom 3D model (dice/acorn-d6.glb, generated by
//    tools/acorn/build_acorn.py) with its own physics shape: a hexagonal "long
//    die" with pointed ends, read on the face that lands on top. The ends never
//    score (face value 0), so a die balanced on a point reads its nearest face.
//  • Classic — the Legend in the Mist die of the original Mist Engine HUD: a d6
//    on a d12 body (each number twice, the 6 shown as the raven / Greatness
//    marks), wooden colorset.
//
// A world setting chooses which set every d6 of every roll uses (the same for
// all players), or leaves it to each player's own Dice So Nice settings.

import { MODULE_ID, L, modulePath } from "./constants.js";
import { ACORN_SHAPE } from "./acorn-shape.js";

export const DICE_SYSTEMS = {
  acorn:   "mist-hud-litm-acorn",
  classic: "mist-hud-litm-classic",
};
export const DICE_SETTING = "diceSet";            // "acorn" | "classic" | "player"

let ready = false;

export function registerDiceSettings() {
  const K = (k) => `MistHUD.settings.${k}`;
  if (game.settings.settings.has(`${MODULE_ID}.${DICE_SETTING}`)) return;
  game.settings.register(MODULE_ID, DICE_SETTING, {
    name: K("diceSet.name"), hint: K("diceSet.hint"),
    scope: "world", config: true, type: String, default: "acorn",
    choices: {
      acorn:   K("diceSet.acorn"),
      classic: K("diceSet.classic"),
      player:  K("diceSet.player"),
    },
  });
}

/** Load Dice So Nice's public DiceSystem class (its documented api.js). */
async function loadDiceSystemClass() {
  try {
    const url = new URL(foundry.utils.getRoute("modules/dice-so-nice/api.js"), window.location.origin).href;
    return (await import(url)).DiceSystem ?? null;
  } catch (e) {
    return null;
  }
}

async function makeSystem(id, name) {
  const DiceSystem = await loadDiceSystemClass();
  return DiceSystem ? new DiceSystem(id, name, "default", "Legend in the Mist") : { id, name, group: "Legend in the Mist" };
}

export async function registerDiceSets(dice3d) {
  if (!dice3d || ready) return;
  const systems = dice3d.DiceFactory?.systems;

  // ── Acorns (needs custom physics shapes: Dice So Nice 6+) ──────────────────
  if (typeof dice3d.addDiceShape === "function" && !systems?.has?.(DICE_SYSTEMS.acorn)) {
    dice3d.addDiceShape(ACORN_SHAPE);
    dice3d.addSystem(await makeSystem(DICE_SYSTEMS.acorn, L("dice.acornName")));
    dice3d.addDicePreset({
      type: "d6",
      system: DICE_SYSTEMS.acorn,
      modelFile: modulePath("dice/acorn-d6.glb"),
    }, ACORN_SHAPE.name);
  }

  // ── Classic Legend in the Mist die (from the original Mist Engine HUD) ─────
  if (!systems?.has?.(DICE_SYSTEMS.classic)) {
    dice3d.addSystem(await makeSystem(DICE_SYSTEMS.classic, L("dice.classicName")));
    const img = (f) => "/" + modulePath(`ui/dice/${f}`);
    dice3d.addDicePreset({
      system: DICE_SYSTEMS.classic,
      type: "d6",
      labels: ["1", "2", "3", "4", "5", img("dice_greatness_color.png"),
        img("dice_raven_color.png"), "5", "4", "3", "2", "1"],
      bumpMaps: [, , , , , img("dice_greatness_bump.png"), img("dice_raven_bump.png"), , , , ,],
      colorset: "mist-hud-litm-legend",
    }, "d12");
    dice3d.addColorset({
      name: "mist-hud-litm-legend",
      description: "Legend in the Mist (Mist Engine HUD)",
      category: "Legend in the Mist",
      foreground: ["#000000", "#000000", "#000000", "#000000"],
      background: ["#e9e1d6", "#828559", "#658686", "#c9ac89"],
      outline: ["#000000", "#000000", "#000000", "#000000"],
      edge: ["#f8f3eb", "#b6b694", "#719481", "#e9dcbc"],
      texture: "wood",
      material: "stone",
      font: "Times",
      visibility: "visible",
    });
  }
  ready = true;
}

/** The dice set every d6 should use, or null to keep each player's own choice. */
export function chosenDiceSystem() {
  const mode = game.settings.get(MODULE_ID, DICE_SETTING);
  const id = DICE_SYSTEMS[mode];
  if (!id) return null;
  if (!game.dice3d?.DiceFactory?.systems?.has?.(id)) return null;
  return id;
}

/**
 * Right before Dice So Nice animates a roll, give every d6 the chosen set
 * (as the original Mist Engine HUD did), unless the roll already asks for a
 * specific set.
 */
export function onRollStart(_messageId, context) {
  if (!ready) return;
  const system = chosenDiceSystem();
  if (!system) return;
  const roll = context?.dsnRoll ?? context?.roll;
  for (const term of roll?.dice ?? []) {
    if (term.faces !== 6) continue;
    term.options ??= {};
    const appearance = (term.options.appearance ??= {});
    appearance.system ??= system;
  }
}
